import { atom, read, update } from 'claude-code'
import type { EngineInterface, PluginOptions, Register } from 'claude-code'

import type { DiffMapData, DiffMapFile, DiffMapSensitive, DiffMapThemes } from '../types'
import { repoContext, runChecks } from './checks'
import { PART_BUDGET, mergeThemes, needsParts, planParts } from './chunks'
import { buildDiagramHtml } from './diagram'
import { isGenerated, reviewPaths } from './model'
import { PROMPT_VERSION, buildPrompt, buildStitchPrompt, parseDiff, parseStitch, parseThemes } from './parse'
import type { ParsedDiff } from './parse'
import type { StrategyKey } from './review-order'
import { sensitiveTags } from './sensitive'
import { loadCachedThemes, saveCachedThemes, sha256 } from './store'

const MAX_UNTRACKED = 60
const STRATEGY_KEYS: readonly string[] = ['theme', 'bottom-up', 'top-down', 'model']

/** What the manifest's `userConfig` says, read once per load of the module. */
type Settings = {
  model: string
  defaultOrder: StrategyKey
  repoChecks: boolean
  lineChecks: boolean
  sensitiveAreas: boolean
  openBrowser: boolean
  /** owner/name to read pull requests from when none is named. */
  repo: string
}

/** The repository pull requests are read from when none is named. */
const DEFAULT_REPO = 'Heal8/healee-platform'
const DEFAULT_OWNER = 'Heal8'

const DEFAULTS: Settings = { model: 'sonnet', defaultOrder: 'theme', repoChecks: true, lineChecks: true, sensitiveAreas: true, openBrowser: true, repo: DEFAULT_REPO }

/** owner/name, or just a name, which belongs to the default owner. */
const REPO_PATTERN = /^(?:[\w.-]+\/)?[\w.-]+$/
const normalizeRepo = (value: string) => (value.includes('/') ? value : `${DEFAULT_OWNER}/${value}`)

let settings: Settings = DEFAULTS

function readSettings(options: PluginOptions): Settings {
  const text = (key: string, fallback: string) => (typeof options[key] === 'string' ? (options[key] as string) : fallback)
  const flag = (key: string, fallback: boolean) => (typeof options[key] === 'boolean' ? (options[key] as boolean) : fallback)
  const order = text('defaultOrder', DEFAULTS.defaultOrder)
  return {
    model: text('model', DEFAULTS.model),
    defaultOrder: STRATEGY_KEYS.includes(order) ? (order as StrategyKey) : DEFAULTS.defaultOrder,
    repoChecks: flag('repoChecks', DEFAULTS.repoChecks),
    lineChecks: flag('lineChecks', DEFAULTS.lineChecks),
    sensitiveAreas: flag('sensitiveAreas', DEFAULTS.sensitiveAreas),
    openBrowser: flag('openBrowser', DEFAULTS.openBrowser),
    repo: REPO_PATTERN.test(text('repo', '').trim()) ? normalizeRepo(text('repo', '').trim()) : DEFAULTS.repo,
  }
}

/** The settings as `/review-map config` names them; `values` is every value a text setting takes. */
/** `values` is every value a text setting takes; `pattern` and `hint` stand in for a free-text one. */
const SETTING_ROWS: { key: keyof Settings; title: string; values?: readonly string[]; pattern?: RegExp; hint?: string }[] = [
  { key: 'model', title: 'Model', values: ['sonnet', 'opus', 'haiku'] },
  { key: 'defaultOrder', title: 'Default review order', values: STRATEGY_KEYS },
  { key: 'repoChecks', title: 'Repo convention checks' },
  { key: 'lineChecks', title: 'Added-line checks' },
  { key: 'sensitiveAreas', title: 'Sensitive-area flags' },
  { key: 'openBrowser', title: 'Open the diagram in the browser' },
  { key: 'repo', title: 'Default repository for pull requests', pattern: REPO_PATTERN, hint: 'owner/name, or just a name for a repository of Heal8' },
]

const showSetting = (value: string | boolean) => (typeof value === 'boolean' ? (value ? 'on' : 'off') : value === '' ? 'none' : value)

const choicesOf = (row: (typeof SETTING_ROWS)[number]) => {
  if (row.hint) return row.hint
  const values = row.values ?? ['on', 'off']
  return `${values.slice(0, -1).join(', ')} or ${values[values.length - 1]}`
}

const settingLine = (row: (typeof SETTING_ROWS)[number], current: Settings) => {
  const value = current[row.key]
  const note = value === DEFAULTS[row.key] ? ' (default)' : ` (default: ${showSetting(DEFAULTS[row.key])})`
  return `  ${row.title} [${row.key}]: ${showSetting(value)}${note}. ${choicesOf(row)}.`
}

const SETTINGS_JSON = (key: string, value: string | boolean) =>
  `  "pluginConfigs": { "review-map@inline": { "options": { ${JSON.stringify(key)}: ${JSON.stringify(value)} } } }`

/** What `/review-map config` prints: each setting as it stands now, and how to change them. */
function configText(current: Settings): string {
  return [
    'review-map settings',
    ...SETTING_ROWS.map(row => settingLine(row, current)),
    '',
    'Change one here: /review-map config <name> <value>, for example /review-map config model opus. The word default puts it back.',
    'Or in the /config menu, where each one is a row named as above, or in ~/.claude/settings.json (then run /reload-plugins):',
    SETTINGS_JSON('model', 'opus'),
  ].join('\n')
}

/** Reads what was typed as a setting's value; undefined when the setting does not take it. */
function parseSettingValue(row: (typeof SETTING_ROWS)[number], raw: string): string | boolean | undefined {
  const text = raw.trim().toLowerCase()
  if (text === 'default' || text === 'reset') return DEFAULTS[row.key]
  if (row.pattern) return row.pattern.test(raw.trim()) ? normalizeRepo(raw.trim()) : undefined
  if (row.values) return row.values.includes(text) ? text : undefined
  if (['on', 'true', 'yes', '1'].includes(text)) return true
  if (['off', 'false', 'no', '0'].includes(text)) return false
  return undefined
}

/** `/review-map config <name> [value]`: shows one setting, or changes it through the /config row it belongs to. */
async function changeSetting($: EngineInterface, args: readonly string[]): Promise<string> {
  const [name = '', ...rest] = args
  const row = SETTING_ROWS.find(r => r.key.toLowerCase() === name.toLowerCase())
  if (!row) return `Unknown setting "${name}". The settings are: ${SETTING_ROWS.map(r => r.key).join(', ')}.`
  if (rest.length === 0) return `${settingLine(row, settings).trim()}\nChange it with /review-map config ${row.key} <value>.`

  const value = parseSettingValue(row, rest.join(' '))
  if (value === undefined) return `"${rest.join(' ')}" is not a value for ${row.key}. Choose ${choicesOf(row)}, or default.`

  const before = settings[row.key]
  const fallback = `Set it in the /config menu instead, or in ~/.claude/settings.json (then run /reload-plugins):\n${SETTINGS_JSON(row.key, value)}`
  const rows = await $.config.list().catch(() => [])
  const found = rows.find(r => r.key.startsWith('review-map') && r.key.endsWith(`.${row.key}`))
  if (found?.isLocked) return `${row.title} is locked by your organisation's settings and cannot be changed here.`

  const result = await $.config.set({ key: found?.key ?? `review-map.${row.key}`, value }).catch(error => ({ failed: String((error as Error).message ?? error) }))
  if ('failed' in result) return `Could not change ${row.key} from the command (${result.failed}). ${fallback}`
  if ('deny' in result) return `Could not change ${row.key} (${String(result.deny)}). ${fallback}`

  settings = { ...settings, [row.key]: value }
  return `${row.title} [${row.key}] is now ${showSetting(value)} (it was ${showSetting(before)}). It applies to the next /review-map.`
}

/** The last mapped change, kept so the same request can reopen its diagram. */
const data = atom({ plugin: 'review-map', key: 'data' } as const, null)

type Source = { kind: 'local' } | { kind: 'pr'; number: string; repo?: string }

const keyOf = (source: Source) => (source.kind === 'pr' ? `pr:${source.repo && source.repo !== DEFAULT_REPO ? `${source.repo}#` : ''}${source.number}` : 'local')

/** Each run gets a number; only the latest one writes, so a newer run supersedes an older one. */
let runId = 0

/** True while a run started by the command should open the diagram once it has finished. */
let openWhenDone = false

type Collected = { title: string; label: string; diff: string; scope: string }

async function collectDiff($: EngineInterface, source: Source): Promise<Collected> {
  const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'])
  const scope = top.exitCode === 0 ? top.stdout.trim() : ''

  if (source.kind === 'pr') {
    const repoArgs = source.repo ? ['--repo', source.repo] : []
    // gh finds the repository from the folder; outside a clone it cannot, and its own message does not say what to do
    const explain = (stderr: string, what: string) =>
      !source.repo && /not a git repository|could not determine base repo/i.test(stderr)
        ? `gh cannot tell which repository PR #${source.number} is in, because this folder is not a git clone. Run /review-map from inside a clone, add --repo owner/name (for example --repo Heal8/healee-platform), or set a default with /review-map config repo owner/name.`
        : stderr.trim() || `${what} failed`
    const info = await $.process.run(
      ['gh', 'pr', 'view', source.number, ...repoArgs, '--json', 'title,number,baseRefName,headRefName,author'],
      { timeoutMs: 60_000 },
    )
    if (info.exitCode !== 0) throw new Error(explain(info.stderr, `gh pr view ${source.number}`))
    const pr = JSON.parse(info.stdout) as {
      title: string
      number: number
      baseRefName: string
      headRefName: string
      author?: { login?: string }
    }
    const diff = await $.process.run(['gh', 'pr', 'diff', source.number, ...repoArgs], { timeoutMs: 120_000 })
    if (diff.exitCode !== 0) throw new Error(explain(diff.stderr, `gh pr diff ${source.number}`))
    return {
      title: `PR #${pr.number}: ${pr.title}`,
      label: `${pr.headRefName} → ${pr.baseRefName}${pr.author?.login ? ` · @${pr.author.login}` : ''}`,
      diff: diff.stdout,
      scope,
    }
  }

  if (top.exitCode !== 0) throw new Error('This folder is not a git repository, so there are no uncommitted changes to map. Run /review-map from inside a clone, or give a PR number with --repo owner/name.')
  const cwd = scope
  const branch = (await $.process.run(['git', 'branch', '--show-current'], { cwd })).stdout.trim() || 'detached HEAD'

  const tracked = await $.process.run(['git', 'diff', 'HEAD', '-M', '--no-color', '--no-ext-diff'], { cwd, timeoutMs: 60_000 })
  if (tracked.exitCode !== 0) throw new Error(tracked.stderr.trim() || 'git diff failed')

  const untrackedList = await $.process.run(['git', 'ls-files', '--others', '--exclude-standard', '-z'], { cwd })
  const untracked = untrackedList.stdout.split('\0').filter(Boolean)
  const pieces = [tracked.stdout]
  for (const file of untracked.slice(0, MAX_UNTRACKED)) {
    // exit code 1 is git's "files differ", the normal answer here
    const one = await $.process.run(['git', 'diff', '--no-index', '--no-color', '--', '/dev/null', file], { cwd })
    pieces.push(one.stdout)
  }
  const skipped = untracked.length - MAX_UNTRACKED
  return {
    title: `Uncommitted changes on ${branch}`,
    label: skipped > 0 ? `working tree vs HEAD (${skipped} untracked files not shown)` : 'working tree vs HEAD, untracked included',
    diff: pieces.join('\n'),
    scope,
  }
}


type Mapped = { themes?: DiffMapThemes; rawThemes?: string; error?: string }

const describeFailure = (reply: { reason: string; status?: number | null }) =>
  reply.reason === 'api-error' ? `API error ${reply.status ?? ''}`.trim() : reply.reason

/** Runs `fn` over the items, at most `limit` at a time, keeping the results in order. */
async function mapLimit<T, R>(items: readonly T[], limit: number, fn: (item: T, index: number) => Promise<R>): Promise<R[]> {
  const out = new Array<R>(items.length)
  let next = 0
  const worker = async () => {
    while (next < items.length) {
      const i = next++
      out[i] = await fn(items[i] as T, i)
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, worker))
  return out
}

/** A change that fits one call: one question to the model. */
async function mapWhole($: EngineInterface, title: string, parsed: ParsedDiff): Promise<Mapped> {
  const reply = await $.model.complete({
    model: settings.model,
    prompt: buildPrompt(title, parsed, repoContext(parsed.files)),
    maxTokens: 8_000,
    timeoutMs: 240_000,
  })
  if (!reply.isAnswered) return { error: `Could not group the changes: ${describeFailure(reply)}` }
  const themes = parseThemes(reply.text, parsed.files)
  return themes ? { themes } : { rawThemes: reply.text }
}

/**
 * A change too big for one call: each part (folders kept together) is mapped by itself, three at a
 * time, then one more call relates the parts to each other. A part that fails leaves its files under
 * "Not mapped" instead of failing the whole map.
 */
async function mapInParts($: EngineInterface, title: string, parsed: ParsedDiff): Promise<Mapped> {
  const plan = planParts(parsed.files, Object.fromEntries(parsed.patches))
  $.ui.toast(`Large change: mapping it in ${plan.parts.length} parts…`)
  const context = repoContext(parsed.files)

  const results = await mapLimit(plan.parts, 3, async (files, i) => {
    const part: ParsedDiff = { files, patches: new Map(files.map(f => [f.path, parsed.patches.get(f.path) ?? ''])) }
    const reply = await $.model.complete({
      model: settings.model,
      prompt: buildPrompt(title, part, context, { budget: PART_BUDGET, perFileCap: plan.perFileCap, part: { index: i + 1, total: plan.parts.length } }),
      maxTokens: 8_000,
      timeoutMs: 240_000,
    })
    if (!reply.isAnswered) return { files, error: describeFailure(reply) }
    const themes = parseThemes(reply.text, files)
    return themes ? { files, themes } : { files, error: 'the reply could not be read' }
  })

  const mapped = results.flatMap(r => (r.themes ? [r.themes] : []))
  const failed = results.filter(r => r.themes === undefined)
  if (mapped.length === 0) return { error: `Could not group the changes: ${failed[0]?.error ?? 'no reply'}` }
  if (failed.length > 0) {
    mapped.push({
      summary: '',
      groups: [{ title: 'Not mapped', kind: 'other', risk: 'low', why: 'the model call for these files failed', files: failed.flatMap(r => r.files).map(f => ({ path: f.path, notes: [] })) }],
      reviewOrder: [],
      concerns: [],
      links: [],
    })
  }

  // the links and the flow take room: a reply cut short would lose the summary with them
  const stitched = await $.model.complete({ model: settings.model, prompt: buildStitchPrompt(title, mapped), maxTokens: 8_000, timeoutMs: 180_000 })
  const stitch = stitched.isAnswered ? parseStitch(stitched.text, parsed.files) : undefined
  if (!stitched.isAnswered) $.ui.toast(`Joining the parts failed (${describeFailure(stitched)}), so the diagram has no links between the parts and no run-time flow.`)
  else if (!stitch) $.ui.toast("The model's reply that joins the parts could not be read, so the diagram has no links between the parts and no run-time flow.")
  return { themes: mergeThemes(mapped, stitch) }
}

/** Reads the change, maps it, and keeps the result; the finishing step opens the diagram when asked to. */
async function generate($: EngineInterface, source: Source, id: number, isForced: boolean) {
  await mapChange($, source, id, isForced)
  if (openWhenDone) await autoOpen($, id)
}

async function mapChange($: EngineInterface, source: Source, id: number, isForced: boolean) {
  const write = async (fn: (current: DiffMapData | null) => DiffMapData | null) => {
    if (id === runId) await update($, data, fn)
  }

  let collected: Collected
  try {
    collected = await collectDiff($, source)
  } catch (error) {
    const message = String((error as Error).message ?? error)
    await write(current => current && { ...current, phase: 'error', error: message })
    if (id === runId && openWhenDone) {
      openWhenDone = false
      $.ui.log(`review-map: ${message}`)
      $.ui.toast(`Could not map the changes: ${message}`)
    }
    return
  }

  const key = keyOf(source)
  const parsed = parseDiff(collected.diff)
  const patches = Object.fromEntries(parsed.patches)
  const sensitive: Record<string, DiffMapSensitive[]> = {}
  if (settings.sensitiveAreas) {
    for (const file of parsed.files) {
      const tags = sensitiveTags(file.path, patches[file.path] ?? '')
      if (tags.length > 0) sensitive[file.path] = tags
    }
  }
  const base: DiffMapData = {
    key,
    ...(source.kind === 'pr' && source.repo ? { repo: source.repo } : {}),
    storeKey: `${collected.scope}|${key}`,
    source: collected.label,
    title: collected.title,
    files: parsed.files,
    phase: 'thinking',
    patches,
    checks: runChecks(parsed.files, patches, { repo: settings.repoChecks, lines: settings.lineChecks }),
    sensitive,
  }

  if (parsed.files.length === 0) {
    await write(() => ({ ...base, phase: 'done' }))
    return
  }

  // the same diff mapped before needs no model call
  const cacheKey = await sha256(`${PROMPT_VERSION}|${settings.model}|${collected.diff}`)
  const cached = isForced ? undefined : await loadCachedThemes($, cacheKey).catch(() => undefined)
  if (cached) {
    await write(() => ({ ...base, phase: 'done', themes: { ...cached, concerns: cached.concerns ?? [], links: cached.links ?? [] }, isCached: true }))
    return
  }
  await write(() => base)

  const mapped = needsParts(parsed.files, patches) ? await mapInParts($, collected.title, parsed) : await mapWhole($, collected.title, parsed)
  if (mapped.error) {
    const message = mapped.error
    await write(current => current && { ...current, phase: 'error', error: message })
    return
  }
  const { themes, rawThemes } = mapped
  await write(current => current && { ...current, phase: 'done', ...(themes ? { themes } : { rawThemes }) })
  if (themes) await saveCachedThemes($, cacheKey, themes).catch(() => undefined)
}

function start($: EngineInterface, source: Source, isForced = false, shouldOpen = false) {
  const id = ++runId
  openWhenDone = shouldOpen
  const title = source.kind === 'pr' ? `PR #${source.number}` : 'Uncommitted changes'
  const loading: DiffMapData = { key: keyOf(source), storeKey: '', source: '', title, files: [], phase: 'loading' }
  return update($, data, () => loading).then(() => {
    // detach from the command's dispatch so the prompt is free while the model works
    $.clock.after(1, () => void generate($, source, id, isForced))
  })
}

/** `--refresh` maps again even when the same diff was mapped before; the rest names the pull request. */
function parseArgs(args: string): { source: Source | { error: string }; wantsRefresh: boolean; repo?: string } {
  const tokens = args.trim().split(/\s+/).filter(Boolean)
  const rest: string[] = []
  let wantsRefresh = false
  let repo: string | undefined
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i] as string
    if (token === '--refresh') wantsRefresh = true
    else if (token === '--repo' || token.startsWith('--repo=')) {
      const value = token === '--repo' ? (tokens[++i] ?? '') : token.slice('--repo='.length)
      if (!REPO_PATTERN.test(value)) return { source: { error: `--repo takes owner/name, or just a name for a repository of ${DEFAULT_OWNER}, for example --repo healee-md. Got "${value}".` }, wantsRefresh }
      repo = normalizeRepo(value)
    } else if (token.startsWith('--')) {
      return { source: { error: `Unknown option ${token}. The command takes an optional PR number or URL, --refresh, --repo [owner/]name, or config.` }, wantsRefresh }
    } else rest.push(token)
  }
  return { source: parseSource(rest.join(' ')), wantsRefresh, repo }
}

function parseSource(args: string): Source | { error: string } {
  const trimmed = args.trim()
  if (trimmed === '') return { kind: 'local' }
  // a pull request's own address says which repository it is in
  const url = trimmed.match(/^https?:\/\/github\.com\/([\w.-]+\/[\w.-]+)\/pull\/(\d+)/)
  if (url?.[1] && url[2]) return { kind: 'pr', number: url[2], repo: url[1] }
  const match = trimmed.match(/^(?:#|.*\/pull\/)?(\d+)\/?$/)
  return match?.[1] ? { kind: 'pr', number: match[1] } : { error: `Expected a PR number or URL, got "${trimmed}"` }
}

/** Opens the diagram of the kept map, as the finishing step of a run or on its own. */
async function autoOpen($: EngineInterface, id?: number) {
  if (id !== undefined && id !== runId) return
  const map = await read($, data)
  if (!map) return
  openWhenDone = false
  if (map.files.length === 0) {
    $.ui.toast('No changes to map.')
    return
  }
  if (map.phase === 'error' && map.error) {
    $.ui.log(`review-map: ${map.error}`)
    $.ui.toast(`${map.error}. The diagram shows the files without themes.`)
  }
  await openDiagram($, map).catch(error => $.ui.toast(`Could not open the diagram: ${String((error as Error).message ?? error)}`))
}

const FULL_FILE_LIMIT = 60
const FULL_FILE_MAX_CHARS = 150_000
const FULL_FILES_TOTAL_CHARS = 3_000_000

/**
 * The files as they stand after the change, for the diagram's "Full file" view: read from disk for
 * local changes, from GitHub at the PR's head commit for a pull request. Best effort, bounded.
 */
async function collectFullFiles($: EngineInterface, map: DiffMapData): Promise<Record<string, string>> {
  const wanted = reviewPaths(map)
    .map(path => map.files.find(f => f.path === path))
    .filter((f): f is DiffMapFile => f !== undefined && f.status !== 'deleted' && f.status !== 'binary' && !isGenerated(f.path))
    .slice(0, FULL_FILE_LIMIT)
  if (wanted.length === 0) return {}

  let load: (path: string) => Promise<string | undefined>
  if (map.key.startsWith('pr:')) {
    // `{owner}/{repo}` is gh's own stand-in for the repository of the folder it runs in
    const repoPath = map.repo ?? '{owner}/{repo}'
    const head = await $.process.run(['gh', 'api', `repos/${repoPath}/pulls/${/(\d+)$/.exec(map.key)?.[1] ?? ''}`, '--jq', '.head.sha'], { timeoutMs: 30_000 }).catch(() => undefined)
    const sha = head?.exitCode === 0 ? head.stdout.trim() : ''
    if (!/^[0-9a-f]{7,64}$/.test(sha)) return {}
    load = async path => {
      const url = `repos/${repoPath}/contents/${path.split('/').map(encodeURIComponent).join('/')}?ref=${sha}`
      const run = await $.process.run(['gh', 'api', '-H', 'Accept: application/vnd.github.raw', url], { timeoutMs: 30_000 }).catch(() => undefined)
      return run?.exitCode === 0 && !run.isStdoutTruncated ? run.stdout : undefined
    }
  } else {
    const root = map.storeKey.split('|')[0] ?? ''
    if (root === '') return {}
    load = async path => {
      const text = await $.fs.read(`${root}/${path}`).catch(() => undefined)
      return typeof text === 'string' ? text : undefined
    }
  }

  const out: Record<string, string> = {}
  let total = 0
  for (let i = 0; i < wanted.length; i += 5) {
    const batch = wanted.slice(i, i + 5)
    const texts = await Promise.all(batch.map(f => load(f.path)))
    batch.forEach((f, j) => {
      const text = texts[j]
      if (text === undefined || text.length > FULL_FILE_MAX_CHARS || total + text.length > FULL_FILES_TOTAL_CHARS) return
      out[f.path] = text
      total += text.length
    })
  }
  return out
}

/** Writes the diagram page to the temp folder and opens it in the browser. */
async function openDiagram($: EngineInterface, map: DiffMapData) {
  $.ui.toast('Building the diagram, collecting the full files…')
  const fullFiles = await collectFullFiles($, map).catch(() => ({}))
  const html = buildDiagramHtml(map, fullFiles, { defaultStrategy: settings.defaultOrder })
  const tmp = ((await $.env.get('TMPDIR')) ?? '/tmp').replace(/\/+$/, '')
  const file = `${tmp}/review-map/${map.key.replace(/[^a-z0-9]+/gi, '-')}.html`
  try {
    await $.fs.write(file, html)
  } catch (error) {
    $.ui.toast(`Could not write the diagram: ${String((error as Error).message ?? error)}`)
    return
  }
  const complete = Object.keys(fullFiles).length
  const noFlow = map.themes && !map.themes.flows?.length && !map.themes.stateCharts?.length && !map.themes.flow && !map.themes.states ? '; the model drew no run-time flow for this change' : ''
  const detail = complete > 0 ? ` (${complete} full files${noFlow})` : noFlow ? ` (${noFlow.slice(2)})` : ''
  if (!settings.openBrowser) {
    $.ui.toast(`Diagram saved to ${file}${detail}`)
    return
  }
  const uname = await $.process.run(['uname']).catch(() => undefined)
  const opener = uname?.stdout.trim() === 'Darwin' ? 'open' : 'xdg-open'
  const opened = await $.process.run([opener, file]).catch(() => undefined)
  $.ui.toast(opened?.exitCode === 0 ? `Diagram opened in your browser${detail}` : `Diagram saved to ${file}${detail}`)
}

export const register: Register = (on, options) => {
  settings = readSettings(options)

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'review-map',
      description: 'Open a diagram of uncommitted changes, or of a pull request (pass its number), in the browser',
      argumentHint: '[PR number] [--refresh] | config [name value]',
    })

    return next(e)
  })

  on('command.run', { command: 'review-map' }, async ($, e) => {
    const words = e.args.trim().split(/\s+/).filter(Boolean)
    if (words[0]?.toLowerCase() === 'config') {
      return { text: words.length === 1 ? configText(settings) : await changeSetting($, words.slice(1)) }
    }

    const parsed = parseArgs(e.args)
    if ('error' in parsed.source) return { text: parsed.source.error }
    // the repository: named in the address or with --repo, else the default setting (healee-platform unless changed)
    const given = parsed.source
    const source: Source = given.kind === 'pr' ? { ...given, repo: given.repo ?? parsed.repo ?? settings.repo } : given
    const where = source.kind === 'pr' ? `PR #${source.number}${source.repo ? ` of ${source.repo}` : ''}` : 'uncommitted changes'

    // the same request again reopens the kept map instead of mapping twice
    const kept = await read($, data)
    const isKept = !parsed.wantsRefresh && kept !== null && kept.key === keyOf(source) && kept.phase !== 'error'
    if (!isKept) {
      await start($, source, parsed.wantsRefresh, true)
      return { text: `Mapping ${where}. The diagram opens in your browser when it is ready.` }
    }
    if (kept.phase === 'loading' || kept.phase === 'thinking') {
      openWhenDone = true
      return { text: `Still mapping ${where}. The diagram opens in your browser when it is ready.` }
    }
    // detach from the command's dispatch: collecting the full files takes a moment
    $.clock.after(1, () => void autoOpen($))
    return { text: `Reopening the diagram of ${where} in your browser.` }
  })
}

