import type { DiffMapCheck, DiffMapFile } from '../types'
import { isDocs, isGenerated, isTest } from './model'

const AREAS = ['healee', 'healee-md', 'shared', 'shared-api'] as const
const SOURCE_RE = /\.(js|jsx|ts|tsx|mjs|cjs|pug)$/
const CODE_RE = /\.(js|jsx|ts|tsx|mjs|cjs)$/
const KEBAB_RE = /^[a-z0-9]+(?:[-.][a-z0-9]+)*\.(js|ts|mjs|cjs)$/

export const areaOf = (path: string) => path.split('/')[0] ?? ''
export const isHealeeRepo = (files: readonly DiffMapFile[]) => files.some(f => (AREAS as readonly string[]).includes(areaOf(f.path)))

/** What the model is told about this repo when the change touches it. */
export function repoContext(files: readonly DiffMapFile[]): string {
  if (!isHealeeRepo(files)) return ''
  return `Repository context (Healee telehealth platform monorepo): healee/ is the patient app (Express + Pug/Kendo/React), healee-md/ the specialist app and its Panel Admin (healee-md/public/js/panel/), shared/ code used by both apps, shared-api/ the NestJS API services, white/ the white-label overlay. Migrations live in */migrations/, localization in */modules/localization/*.js (en and bg must stay in step). Conventions reviewers enforce: tabs for indentation, double quotes, kebab-case file names, one module.exports at the bottom of a file, HTTP handlers suffixed Handler, DB indexes declared after the schema, React dialogs built on BaseDialog. Name themes by these layers where it helps (e.g. "patient app UI", "shared-api endpoint") and call out cross-app impact: a change under shared/ reaches both apps.\n\n`
}

const addedLines = (patch: string) => patch.split('\n').filter(l => l.startsWith('+') && !l.startsWith('+++'))

const plural = (n: number, one: string, many = `${one}s`) => `${n} ${n === 1 ? one : many}`

/** Repo-convention checks on the diff itself: deterministic, no model involved. */
export type CheckOptions = { repo: boolean; lines: boolean }

export function runChecks(files: readonly DiffMapFile[], patches: Record<string, string>, options: CheckOptions = { repo: true, lines: true }): DiffMapCheck[] {
  if (!isHealeeRepo(files) || !options.repo) return options.lines ? runGenericChecks(files, patches) : []
  const out: DiffMapCheck[] = []
  const paths = new Set(files.map(f => f.path))

  // localization: en and bg move together
  for (const file of files) {
    const match = file.path.match(/^(.*\/modules\/localization\/)(en|bg)\.js$/)
    if (!match?.[1] || !match[2]) continue
    const other = `${match[1]}${match[2] === 'en' ? 'bg' : 'en'}.js`
    if (!paths.has(other)) {
      out.push({ severity: 'warn', text: `${match[2]}.js changed but ${other.split('/').pop()} did not (the localization check enforces en and bg parity)`, path: file.path })
    }
  }

  // migrations: reversible
  for (const file of files) {
    if (file.status === 'added' && /(^|\/)migrations\/[^/]+\.js$/.test(file.path) && !/\bdown\b/.test(patches[file.path] ?? '')) {
      out.push({ severity: 'warn', text: 'New migration has no down(), so make migrations-down cannot roll it back', path: file.path })
    }
  }

  // tests: an area whose source changed with no test in the same area
  for (const area of AREAS) {
    const inArea = files.filter(f => areaOf(f.path) === area)
    const source = inArea.filter(f => SOURCE_RE.test(f.path) && !isTest(f.path) && !isDocs(f.path) && !isGenerated(f.path) && !/(^|\/)migrations\//.test(f.path))
    if (source.length > 0 && !inArea.some(f => isTest(f.path))) {
      out.push({ severity: 'info', text: `No tests touched in ${area}/ (${plural(source.length, 'source file')} changed)` })
    }
  }

  // Superdoc contract
  const superdoc = files.find(f => /superdoc/i.test(f.path) && !isTest(f.path) && !isDocs(f.path))
  if (superdoc && !paths.has('docs/SUPERDOC-HEALEE-API.md')) {
    out.push({ severity: 'info', text: 'Superdoc-facing code changed; docs/SUPERDOC-HEALEE-API.md is the contract the Superdoc team reads', path: superdoc.path })
  }

  for (const file of files) {
    if (file.status === 'deleted' || file.status === 'binary') continue
    const patch = patches[file.path] ?? ''
    if (!CODE_RE.test(file.path) || isGenerated(file.path) || file.path.startsWith('white/')) continue
    const added = addedLines(patch)

    const spaced = added.filter(l => /^\+ {2,}\S/.test(l)).length
    if (spaced > 0) out.push({ severity: 'warn', text: `${plural(spaced, 'added line')} indented with spaces (the repo uses tabs)`, path: file.path })

    const single = added.filter(l => /\bfrom '|\brequire\('/.test(l)).length
    if (single > 0) out.push({ severity: 'warn', text: `${plural(single, 'import')} with single quotes (the repo uses double quotes)`, path: file.path })

    if (file.status === 'added') {
      const name = file.path.split('/').pop() ?? file.path
      const isComponent = /\.tsx?$/.test(name) && /^[A-Z]/.test(name)
      const isHook = /^use[A-Z]/.test(name)
      if (!isComponent && !isHook && /\.(js|ts|mjs|cjs)$/.test(name) && !KEBAB_RE.test(name)) {
        out.push({ severity: 'warn', text: `File name ${name} is not kebab-case`, path: file.path })
      }
    }

    if (options.lines) out.push(...runLineChecks(file, added))
  }
  return out
}

/** Checks that need no repo knowledge: left-in debugging and focused tests. */
function runGenericChecks(files: readonly DiffMapFile[], patches: Record<string, string>): DiffMapCheck[] {
  const out: DiffMapCheck[] = []
  for (const file of files) {
    if (file.status === 'deleted' || file.status === 'binary' || !CODE_RE.test(file.path) || isGenerated(file.path)) continue
    out.push(...runLineChecks(file, addedLines(patches[file.path] ?? '')))
  }
  const source = files.filter(f => SOURCE_RE.test(f.path) && !isTest(f.path) && !isDocs(f.path) && !isGenerated(f.path))
  if (source.length > 0 && !files.some(f => isTest(f.path))) {
    out.push({ severity: 'info', text: `No test files in this change (${plural(source.length, 'source file')} changed)` })
  }
  return out
}

function runLineChecks(file: DiffMapFile, added: readonly string[]): DiffMapCheck[] {
  const out: DiffMapCheck[] = []
  const debuggers = added.filter(l => /\bdebugger\b/.test(l)).length
  if (debuggers > 0) out.push({ severity: 'warn', text: 'debugger statement added', path: file.path })

  const focused = added.filter(l => /\b(describe|it|test)\.only\(/.test(l)).length
  if (focused > 0) out.push({ severity: 'warn', text: '.only( left in a test, the rest of the suite would be skipped', path: file.path })

  if (!isTest(file.path)) {
    const logs = added.filter(l => /\bconsole\.(log|debug)\(/.test(l)).length
    if (logs > 0) out.push({ severity: 'info', text: `${plural(logs, 'console.log call')} added`, path: file.path })
  }
  return out
}

