import type { DiffMapFile, DiffMapFlow, DiffMapGroup, DiffMapLink, DiffMapStateChart, DiffMapThemes } from '../types'
import { isGenerated } from './model'

/** What one model call carries before a change is split up. */
export const SINGLE_BUDGET = 150_000

/** What each part of a split change may carry. */
export const PART_BUDGET = 110_000

const FILE_CAPS = [12_000, 6_000, 2_500]
const MAX_PARTS = 10
const LIST_LINE = 200

type Patches = Readonly<Record<string, string>>

const weight = (file: DiffMapFile, patches: Patches, cap: number) =>
  (isGenerated(file.path) ? 0 : Math.min(patches[file.path]?.length ?? 0, cap)) + LIST_LINE

const total = (files: readonly DiffMapFile[], patches: Patches, cap: number) => files.reduce((sum, f) => sum + weight(f, patches, cap), 0)

/** True when the whole diff would not fit one call without cutting files short. */
export function needsParts(files: readonly DiffMapFile[], patches: Patches): boolean {
  return total(files, patches, Number.POSITIVE_INFINITY) > SINGLE_BUDGET
}

const dirKey = (path: string, depth: number) => path.split('/').slice(0, -1).slice(0, depth).join('/')

/** Splits a folder's files, going a level deeper into the tree for as long as the folder is too big. */
function split(files: DiffMapFile[], patches: Patches, cap: number, budget: number, depth: number): DiffMapFile[][] {
  if (total(files, patches, cap) <= budget) return [files]
  if (depth > 6) return slices(files, patches, cap, budget)
  const groups = new Map<string, DiffMapFile[]>()
  for (const file of files) groups.set(dirKey(file.path, depth), [...(groups.get(dirKey(file.path, depth)) ?? []), file])
  if (groups.size === 1) return split(files, patches, cap, budget, depth + 1)
  return [...groups.values()].flatMap(group => split(group, patches, cap, budget, depth + 1))
}

function slices(files: DiffMapFile[], patches: Patches, cap: number, budget: number): DiffMapFile[][] {
  const out: DiffMapFile[][] = []
  let current: DiffMapFile[] = []
  let size = 0
  for (const file of files) {
    const w = weight(file, patches, cap)
    if (current.length > 0 && size + w > budget) {
      out.push(current)
      current = []
      size = 0
    }
    current.push(file)
    size += w
  }
  if (current.length > 0) out.push(current)
  return out
}

/** Folders that are small enough to share a part are packed together, in path order. */
function pack(parts: DiffMapFile[][], patches: Patches, cap: number, budget: number): DiffMapFile[][] {
  const out: DiffMapFile[][] = []
  let current: DiffMapFile[] = []
  for (const part of parts) {
    if (current.length > 0 && total([...current, ...part], patches, cap) > budget) {
      out.push(current)
      current = []
    }
    current = [...current, ...part]
  }
  if (current.length > 0) out.push(current)
  return out
}

export type PartPlan = { parts: DiffMapFile[][]; perFileCap: number }

/**
 * Splits a big change into parts that each fit one call, keeping files of a folder together.
 * A change that would need too many parts is planned again with each file's diff cut shorter.
 */
export function planParts(files: readonly DiffMapFile[], patches: Patches, budget = PART_BUDGET): PartPlan {
  const sorted = [...files].sort((a, b) => a.path.localeCompare(b.path))
  let plan: PartPlan = { parts: [sorted], perFileCap: FILE_CAPS[0] ?? 12_000 }
  for (const cap of FILE_CAPS) {
    plan = { parts: pack(split(sorted, patches, cap, budget, 1), patches, cap, budget), perFileCap: cap }
    if (plan.parts.length <= MAX_PARTS) return plan
  }
  return plan
}

const RISK_RANK = { low: 0, medium: 1, high: 2 } as const

const unique = <T>(items: readonly T[]) => [...new Set(items)]

/** One set of themes from the parts' own: themes of the same title are joined, links and notes kept. */
export function mergeThemes(parts: readonly DiffMapThemes[], extra?: { summary?: string; links?: readonly DiffMapLink[]; flows?: readonly DiffMapFlow[]; stateCharts?: readonly DiffMapStateChart[] }): DiffMapThemes {
  const groups = new Map<string, DiffMapGroup>()
  for (const group of parts.flatMap(p => p.groups)) {
    const key = group.title.trim().toLowerCase()
    const have = groups.get(key)
    if (!have) {
      groups.set(key, { ...group, files: [...group.files] })
      continue
    }
    const known = new Set(have.files.map(f => f.path))
    have.files.push(...group.files.filter(f => !known.has(f.path)))
    if (RISK_RANK[group.risk] > RISK_RANK[have.risk]) have.risk = group.risk
    if (have.why === '') have.why = group.why
  }

  const links: DiffMapLink[] = []
  const seen = new Set<string>()
  for (const link of [...parts.flatMap(p => p.links ?? []), ...(extra?.links ?? [])]) {
    const key = `${link.from}>${link.to}`
    if (seen.has(key)) continue
    seen.add(key)
    links.push(link)
  }

  return {
    summary: extra?.summary || parts.map(p => p.summary).filter(Boolean).join(' ').slice(0, 400),
    groups: [...groups.values()],
    reviewOrder: unique(parts.flatMap(p => p.reviewOrder)),
    concerns: unique(parts.flatMap(p => p.concerns)).slice(0, 12),
    links: links.slice(0, 40),
    ...(extra?.flows?.length ? { flows: [...extra.flows] } : {}),
    ...(extra?.stateCharts?.length ? { stateCharts: [...extra.stateCharts] } : {}),
  }
}

