import type { DiffMapData } from '../types'
import { buildDiagramData } from './diagram-data'
import type { DiagramOptions } from './diagram-data'

const esc = (text: string) =>
  text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;')

const HIDE_CHIPS: { name: string; label: string }[] = [
  { name: 'tests', label: 'Tests' },
  { name: 'docs', label: 'Docs' },
  { name: 'generated', label: 'Generated files' },
  { name: 'lowRisk', label: 'Low-risk lanes' },
  { name: 'reviewed', label: 'Reviewed files' },
]

/**
 * A self-contained HTML page: the change as lanes of files joined by their links, with the diffs inside.
 * The page lays itself out in the browser, so lanes collapse, filters apply and search dims in place.
 */
export function buildDiagramHtml(map: DiffMapData, fullFiles: Readonly<Record<string, string>> = {}, options: DiagramOptions = {}): string {
  const data = buildDiagramData(map, fullFiles, options)
  // `<` is escaped so no diff text can close the script element; the two line separators would end a JS string
  const json = JSON.stringify(data)
    .replace(/</g, '\\u003c')
    .split(String.fromCharCode(0x2028))
    .join('\\u2028')
    .split(String.fromCharCode(0x2029))
    .join('\\u2029')

  const totals = map.files.reduce((s, f) => ({ a: s.a + f.added, r: s.r + f.removed }), { a: 0, r: 0 })
  const items = HIDE_CHIPS.map(c => `<label><input type="checkbox" data-hide="${c.name}"> ${c.label}</label>`).join('\n      ')
  const chips = `<span class="dd" id="hidedd"><button type="button" class="tog dd-btn" id="hidebtn" aria-haspopup="true" aria-expanded="false">Hide: <span id="hidesum">nothing</span> ▾</button>
    <div class="dd-menu" id="hidemenu" hidden>
      ${items}
      <div class="dd-foot"><button type="button" class="linkbtn" id="hideclear">Show everything</button></div>
    </div></span>`

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(map.title.slice(0, 80))} · Review map</title>
<style>${STYLE}</style>
</head>
<body>
<header>
  <h1>${esc(map.title)}</h1>
  <p class="sub">${esc(map.source)}</p>
  <p class="stats"><span>${map.files.length} files</span><span class="add">+${totals.a}</span><span class="del">−${totals.r}</span><span id="reviewedStat">reviewed 0/${map.files.length}</span><span id="shown"></span></p>
  ${map.themes?.summary ? `<p class="summary">${esc(map.themes.summary)}</p>` : ''}
  <!-- the controls stay in the page, out of sight, at their defaults: the script reads and sets them -->
  <div class="toolbar" hidden>
    ${chips}
    <span class="grp"><label class="lbl" for="strategies">Review order</label><select class="sel" id="strategies"></select></span>
    <span class="grp"><label class="lbl map-only" for="pathmodes">Path</label><select class="sel map-only" id="pathmodes"><option value="off">Off</option><option value="next" selected>Next steps</option><option value="all">Whole path</option></select><button type="button" class="tog go" id="gonext">Go to next step</button></span>
    <span class="zoom map-only" role="group" aria-label="Zoom"><button type="button" id="zout" aria-label="Zoom out">−</button><span id="zval">100%</span><button type="button" id="zin" aria-label="Zoom in">+</button><button type="button" id="fit">Fit</button><button type="button" id="z100">100%</button></span>
    <button type="button" class="tog map-only" id="labels" aria-pressed="true">Link labels</button>
    <span class="hint" id="blurb"></span>
  </div>
  <div class="stages" id="stages" aria-label="Review stages"></div>
</header>
<main>
  <div class="leftcol">
  <div class="canvas-wrap" id="canvaswrap">
    <div class="viewbar" id="viewbar" hidden><span class="seg" id="viewtabs" role="group" aria-label="What to show"></span><span class="hint" id="viewtitle"></span></div>
    <div class="canvas" id="canvas"><svg id="map" role="group" aria-label="Changed files grouped by theme, joined by their relationships"></svg></div>
    <div class="flowview" id="flowview" hidden>
      <div class="flowpick" id="flowpick" role="group" aria-label="Which flow to show" hidden></div>
      <div class="flegend"><span class="fl fl-new">new in this change</span><span class="fl fl-chg">changed</span><span class="fl fl-same">existing behaviour</span><span class="hint">Click a step or a box to open its file in the panel. Drag to pan, Ctrl or Cmd + wheel to zoom, double-click to fit.</span></div>
      <div class="flowhost" id="flowhost"></div>
    </div>
    <div class="mini" id="mini" hidden><svg id="miniSvg" aria-hidden="true"></svg></div>
  </div>
  <div class="below">
  <div class="risks" id="risks" hidden></div>
    <p class="legend"><span class="chip risk-low">low risk</span><span class="chip risk-medium">medium risk</span><span class="chip risk-high">high risk</span><span class="hint">${data.links.length > 0 ? 'Numbers are the suggested review order. Hover a file for details, click to read the diff, click a lane title to fold it. Drag the background to pan, Ctrl or Cmd + wheel to zoom.' : 'No links between files were detected. Numbers are the suggested review order. Click a file to read the diff.'}</span></p>
  </div>
  </div>
  <div class="splitter" id="splitter" role="separator" aria-orientation="vertical" aria-label="Resize the panel"></div>
  <aside id="panel">
    <div class="ptabs"><button type="button" id="tablist" aria-pressed="true">Review list</button><button type="button" id="tabfile" aria-pressed="false">File</button></div>
    <div id="pbody" aria-live="polite"><p class="empty">Select a file to see what changed, why it matters, and its diff.</p></div>
  </aside>
</main>
<div id="tip" hidden></div>
<script>
var DATA = ${json};
${SCRIPT}
</script>
</body>
</html>
`
}

