  function unified(parsed, lang, host) {
    var table = h("table", "diff");
    parsed.hunks.forEach(function (hk) {
      var hr = h("tr", "hunk"), hd = h("td", "", hk.head);
      hd.colSpan = 3; hr.appendChild(hd); table.appendChild(hr);
      var st = { block: false }, items = [];
