        tr.appendChild(codeCell("", r, r.t === "m" ? null : lang, st, r.t === "a" ? "+" : r.t === "d" ? "-" : " "));
        table.appendChild(tr);
        items.push({ tr: tr, ctx: r.t === "c" });
