  $("labels").setAttribute("aria-pressed", String(S.labels));
  $("labels").onclick = function () { S.labels = !S.labels; this.setAttribute("aria-pressed", String(S.labels)); svg.classList.toggle("labels-on", S.labels); };

  /* pan by dragging the background; a plain click on it clears the selection */
  canvas.addEventListener("pointerdown", function (e) {
    if (e.button !== 0 || !e.target.closest || e.target.closest(".node, .lane-head, .edge-hit") || e.target.closest("svg") !== svg) return;
    pan = { x: e.clientX, y: e.clientY, sl: canvas.scrollLeft, st: canvas.scrollTop, moved: false };
    canvas.setPointerCapture(e.pointerId);
  });
  canvas.addEventListener("pointermove", function (e) {
    if (!pan) return;
    var dx = e.clientX - pan.x, dy = e.clientY - pan.y;
    if (!pan.moved && Math.hypot(dx, dy) < 4) return;
    pan.moved = true;
    hideTip();
    canvas.classList.add("panning");
    canvas.scrollLeft = pan.sl - dx;
    canvas.scrollTop = pan.st - dy;
  });
  function endPan() {
    if (!pan) return;
    var wasClick = !pan.moved;
    pan = null;
    canvas.classList.remove("panning");
    if (wasClick && S.selected) clearSelection();
  }
  canvas.addEventListener("pointerup", endPan);
  canvas.addEventListener("pointercancel", function () { pan = null; canvas.classList.remove("panning"); });

  /* the divider between graph and panel, and a wide-panel toggle */
  var main = document.querySelector("main"), splitter = $("splitter"), splitting = false;
  function setPanelW(w) {
    var max = Math.max(340, main.clientWidth * 0.78);
    w = Math.max(320, Math.min(max, w));
    main.style.setProperty("--panel-w", w + "px");
    try { localStorage.setItem("diffmap-panel", String(Math.round(w))); } catch (err) { /* private mode */ }
  }
  try { var saved = +localStorage.getItem("diffmap-panel"); if (saved) setPanelW(saved); } catch (err) { /* private mode */ }
  splitter.addEventListener("pointerdown", function (e) { splitting = true; splitter.classList.add("drag"); splitter.setPointerCapture(e.pointerId); });
  splitter.addEventListener("pointermove", function (e) { if (splitting) setPanelW(main.getBoundingClientRect().right - 24 - e.clientX); });
  function endSplit() { splitting = false; splitter.classList.remove("drag"); }
  splitter.addEventListener("pointerup", endSplit);
  splitter.addEventListener("pointercancel", endSplit);
  if (window.ResizeObserver) new ResizeObserver(function () { if (!L) return; if (S.fitMode) fitNow(); else drawMini(); }).observe(canvas);

  /* the hover card: everything a file's node cannot hold */
  function moveTip(e) {
    var w = tip.offsetWidth, hh = tip.offsetHeight, x = e.clientX + 16, y = e.clientY + 16;
    if (x + w > window.innerWidth - 8) x = e.clientX - w - 16;
    if (y + hh > window.innerHeight - 8) y = e.clientY - hh - 16;
    tip.style.left = Math.max(8, x) + "px";
    tip.style.top = Math.max(8, y) + "px";
  }
  function hideTip() { tip.hidden = true; tipPath = null; }
  function showTip(path, e) {
    if (pan && pan.moved) return;
    if (tipPath !== path) {
      tipPath = path;
      var f = files[path];
      tip.textContent = "";
      tip.appendChild(h("div", "tip-path", path));
      var meta = h("div", "tip-meta");
      meta.appendChild(document.createTextNode(f.status + " · "));
      meta.appendChild(h("span", "add", "+" + f.added));
      meta.appendChild(document.createTextNode(" "));
      meta.appendChild(h("span", "del", "−" + f.removed));
      if (rank[path]) meta.appendChild(document.createTextNode(" \u00b7 step " + rank[path] + " of " + ORD.steps.length));
      if (isDone(path)) meta.appendChild(document.createTextNode(" \u00b7 reviewed \u2713"));
      tip.appendChild(meta);
      if (f.group) tip.appendChild(h("div", "tip-group", f.group + (f.risk ? " \u00b7 " + f.risk + " risk" : "")));
      if (reasonOf[path]) tip.appendChild(h("div", "tip-reason", reasonOf[path]));
      f.notes.slice(0, 3).forEach(function (n) { tip.appendChild(h("div", "tip-note", "· " + n)); });
      var warns = f.checks.filter(function (c) { return c.severity === "warn"; }).length;
      if (warns) tip.appendChild(h("div", "tip-warn", "⚠ " + warns + " check" + (warns === 1 ? "" : "s")));
      if (f.risks.length) tip.appendChild(h("div", "tip-risk", "\u2691 " + f.risks.map(function (r) { return r.label; }).join(", ")));
      if (f.links.length) tip.appendChild(h("div", "tip-meta", f.links.length + " link" + (f.links.length === 1 ? "" : "s")));
    }
    tip.hidden = false;
    moveTip(e);
  }

  function toggleLane(li) { if (S.collapsed[li]) delete S.collapsed[li]; else S.collapsed[li] = true; render(); }
  svg.addEventListener("click", function (e) {
    var n = e.target.closest(".node");
    if (n) return pickNode(n.getAttribute("data-path"));
    var hd = e.target.closest(".lane-head");
    if (hd) toggleLane(+hd.getAttribute("data-li"));
  });
  svg.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" && e.key !== " ") return;
    var n = e.target.closest(".node"), hd = e.target.closest(".lane-head");
    if (n) { e.preventDefault(); pickNode(n.getAttribute("data-path")); }
    else if (hd) { e.preventDefault(); toggleLane(+hd.getAttribute("data-li")); }
  });
  function setHover(e) {
    var n = e.target.closest && e.target.closest(".node");
    S.hover = n ? n.getAttribute("data-path") : null;
    var eg = e.target.closest && e.target.closest(".edge");
    labelEls.forEach(function (l) { l.el.classList.toggle("hot", !!eg && l.i === +eg.getAttribute("data-i")); });
    applyFocus();
    if (S.hover && e.type === "mouseover") showTip(S.hover, e);
    else if (!S.hover) hideTip();
  }
  svg.addEventListener("mouseover", setHover);
  svg.addEventListener("mousemove", function (e) { if (S.hover && !tip.hidden) moveTip(e); });
  svg.addEventListener("mouseout", function () { S.hover = null; labelEls.forEach(function (l) { l.el.classList.remove("hot"); }); applyFocus(); hideTip(); });
  svg.addEventListener("focusin", setHover);
  svg.addEventListener("focusout", function () { S.hover = null; applyFocus(); });
  document.addEventListener("keydown", function (e) {
    var typing = /^(input|textarea)$/i.test((e.target && e.target.tagName) || "");
    if (e.key === "Escape" && !$("hidemenu").hidden) setMenu(false);
    else if (e.key === "Escape" && !typing) clearSelection();
  });

  syncStrategy();
  syncPathModes();
  updateStats();
  renderStages();
  renderRisks();
  render();
  refreshPanel();
  /* open on the step to take next, so START or NEXT is never off-screen */
  if (curNext) setTimeout(function () { scrollToNode(curNext); }, 0);
})();
`

