import type { DiffMapData, DiffMapLink } from '../types'

const TEST_RE = /(^|\/)(tests?|__tests__|specs?|e2e|appium)\/|\.(spec|test)\.[cm]?[jt]sx?$/i
const DOCS_RE = /(^|\/)docs?\/|\.(md|mdx|txt|rst)$|(^|\/)(README|CHANGELOG|LICENSE)/i
const GENERATED_RE = /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock)$|\.min\.(js|css)$|\.map$|(^|\/)(dist|build|\.dist)\//

export const isTest = (path: string) => TEST_RE.test(path)
export const isDocs = (path: string) => DOCS_RE.test(path) && !isTest(path)
export const isGenerated = (path: string) => GENERATED_RE.test(path)

/** The model's review order, then whatever it left out: every changed file once. */
export function reviewPaths(map: DiffMapData): string[] {
  const known = new Set(map.files.map(f => f.path))
  const out: string[] = []
  const add = (path: string) => {
    if (known.has(path) && !out.includes(path)) out.push(path)
  }
  for (const path of map.themes?.reviewOrder ?? []) add(path)
  for (const group of map.themes?.groups ?? []) for (const file of group.files) add(file.path)
  for (const file of map.files) add(file.path)
  return out
}

export type LinkView = { other: string; label: string; direction: 'in' | 'out' }

/** The links that touch one file, as `{ other, label, direction }` seen from it. */
export function linksFor(links: readonly DiffMapLink[] | undefined, path: string): LinkView[] {
  return (links ?? []).flatMap((link): LinkView[] => {
    if (link.from === path) return [{ other: link.to, label: link.label, direction: 'out' }]
    if (link.to === path) return [{ other: link.from, label: link.label, direction: 'in' }]
    return []
  })
}

export function groupOf(map: DiffMapData, path: string) {
  for (const group of map.themes?.groups ?? []) {
    const file = group.files.find(f => f.path === path)
    if (file) return { group, notes: file.notes }
  }
  return undefined
}

