import type { DiffMapChange, DiffMapFile, DiffMapFlow, DiffMapGroup, DiffMapLink, DiffMapStateChart, DiffMapThemes } from '../types'

/**
 * The JSON object in a model reply. A reply that was cut off at its token limit is not valid JSON, so
 * the text is closed after the last value that was finished and what came before the cut is kept.
 */
export function readJson(text: string): unknown {
  const start = text.indexOf('{')
  if (start < 0) return undefined
  const body = text.slice(start)
  const end = body.lastIndexOf('}')
  if (end > 0) {
    try {
      return JSON.parse(body.slice(0, end + 1))
    } catch {
      // cut off inside a value, or words after it: fall through to closing it by hand
    }
  }

  const open: string[] = []
  const candidates: { at: number; closers: string }[] = []
  let inString = false
  let escaped = false
  for (let i = 0; i < body.length; i++) {
    const c = body[i]
    if (inString) {
      if (escaped) escaped = false
      else if (c === '\\') escaped = true
      else if (c === '"') inString = false
      continue
    }
    if (c === '"') inString = true
    else if (c === '{') open.push('}')
    else if (c === '[') open.push(']')
    else if (c === '}' || c === ']') {
      open.pop()
      candidates.push({ at: i + 1, closers: [...open].reverse().join('') })
    }
  }
  for (let k = candidates.length - 1; k >= Math.max(0, candidates.length - 400); k--) {
    const candidate = candidates[k]
    if (!candidate) continue
    try {
      return JSON.parse(body.slice(0, candidate.at) + candidate.closers)
    } catch {
      // the cut left a dangling key or comma after this value: try an earlier one
    }
  }
  return undefined
}

/** Bump when the prompt or reply shape changes, so cached themes are not reused. */
export const PROMPT_VERSION = 5

export type ParsedDiff = { files: DiffMapFile[]; patches: Map<string, string> }

const unquote = (path: string) =>
  path.startsWith('"') && path.endsWith('"') ? path.slice(1, -1) : path

const stripPrefix = (path: string) => unquote(path).replace(/^[ab]\//, '')

/** Splits a unified diff (git diff / gh pr diff) into per-file stats and patch text. */
export function parseDiff(text: string): ParsedDiff {
  const files: DiffMapFile[] = []
  const patches = new Map<string, string>()
  const chunks = text.split(/^(?=diff --git )/m).filter(c => c.startsWith('diff --git '))

  for (const chunk of chunks) {
    const lines = chunk.split('\n')
    const first = lines[0] ?? ''
    const header = first.match(/^diff --git (\S+|"[^"]+") (\S+|"[^"]+")$/)
    let oldPath = header?.[1] ? stripPrefix(header[1]) : ''
    let path = header?.[2] ? stripPrefix(header[2]) : first.slice('diff --git '.length)
    let status: DiffMapFile['status'] = 'modified'
    let added = 0
    let removed = 0
    let inHunk = false
    const contexts: string[] = []

    for (const line of lines.slice(1)) {
      if (!inHunk) {
        if (line.startsWith('new file mode')) status = 'added'
        else if (line.startsWith('deleted file mode')) status = 'deleted'
        else if (line.startsWith('rename from ')) { oldPath = line.slice(12); status = 'renamed' }
        else if (line.startsWith('rename to ')) path = line.slice(10)
        else if (line.startsWith('Binary files') || line.startsWith('GIT binary patch')) status = 'binary'
        else if (line.startsWith('+++ ') && line !== '+++ /dev/null') path = stripPrefix(line.slice(4))
      }
      if (line.startsWith('@@')) {
        inHunk = true
        const context = line.replace(/^@@[^@]*@@\s?/, '').trim()
        if (context && !contexts.includes(context)) contexts.push(context)
        continue
      }
      if (!inHunk) continue
      if (line.startsWith('+')) added++
      else if (line.startsWith('-')) removed++
    }

    files.push({
      path,
      ...(status === 'renamed' && oldPath !== path ? { oldPath } : {}),
      status,
      added,
      removed,
      contexts: contexts.slice(0, 8),
    })
    patches.set(path, chunk)
  }

  files.sort((a, b) => a.path.localeCompare(b.path))
  return { files, patches }
}

/** Builds the model prompt: file list plus patches, each patch capped, the whole capped. */
const CHANGES: readonly string[] = ['added', 'changed', 'unchanged']
const KINDS = ['call', 'return', 'async'] as const

const asChange = (value: unknown): DiffMapChange => (CHANGES.includes(value as string) ? (value as DiffMapChange) : 'unchanged')
const clean = (value: unknown, max: number) => (typeof value === 'string' ? value.trim().slice(0, max) : '')
const knownFile = (value: unknown, known: ReadonlySet<string>) => (typeof value === 'string' && known.has(value) ? value : undefined)
const objects = (value: unknown): Record<string, unknown>[] =>
  (Array.isArray(value) ? value : []).filter((v): v is Record<string, unknown> => typeof v === 'object' && v !== null)

/** Reads the run-time sequence the model drew; anything that does not hold together is dropped. */
export function parseFlow(raw: unknown, known: ReadonlySet<string>): DiffMapFlow | undefined {
  if (typeof raw !== 'object' || raw === null) return undefined
  const value = raw as Record<string, unknown>
  const seen = new Set<string>()
  const participants = objects(value.participants)
    .flatMap(p => {
      const id = clean(p.id, 24)
      if (id === '' || seen.has(id)) return []
      seen.add(id)
      const file = knownFile(p.file, known)
      return [{ id, label: clean(p.label, 40) || id, ...(file ? { file } : {}) }]
    })
    .slice(0, 8)
  const steps = objects(value.steps)
    .flatMap(s => {
      const from = clean(s.from, 24)
      const to = clean(s.to, 24)
      if (!seen.has(from) || !seen.has(to) || !participants.some(p => p.id === from) || !participants.some(p => p.id === to)) return []
      const file = knownFile(s.file, known)
      const kind = KINDS.find(k => k === s.kind) ?? 'call'
      return [{ from, to, label: clean(s.label, 80), kind, change: asChange(s.change), ...(file ? { file } : {}) }]
    })
    .slice(0, 16)
  if (participants.length < 2 || steps.length < 2) return undefined
  return { title: clean(value.title, 80) || 'How it runs', participants, steps }
}

const MAX_FLOWS = 4

/** The model may answer with one chart or a list of them; the first few that hold together are kept. */
const listOf = (raw: unknown) => (Array.isArray(raw) ? raw : raw ? [raw] : []).slice(0, MAX_FLOWS + 2)

export function parseFlows(raw: unknown, known: ReadonlySet<string>): DiffMapFlow[] {
  return listOf(raw).flatMap(r => parseFlow(r, known) ?? []).slice(0, MAX_FLOWS)
}

export function parseStateCharts(raw: unknown, known: ReadonlySet<string>): DiffMapStateChart[] {
  return listOf(raw).flatMap(r => parseStates(r, known) ?? []).slice(0, MAX_FLOWS)
}

/** Reads the chart of states the model drew; undefined when it is not a chart (two states, one move). */
export function parseStates(raw: unknown, known: ReadonlySet<string>): DiffMapStateChart | undefined {
  if (typeof raw !== 'object' || raw === null) return undefined
  const value = raw as Record<string, unknown>
  const seen = new Set<string>()
  const states = objects(value.states)
    .flatMap(s => {
      const id = clean(s.id, 32)
      if (id === '' || seen.has(id)) return []
      seen.add(id)
      return [{ id, label: clean(s.label, 40) || id, change: asChange(s.change) }]
    })
    .slice(0, 10)
  const transitions = objects(value.transitions)
    .flatMap(t => {
      const from = clean(t.from, 32)
      const to = clean(t.to, 32)
      if (!states.some(s => s.id === from) || !states.some(s => s.id === to)) return []
      const file = knownFile(t.file, known)
      return [{ from, to, label: clean(t.label, 70), change: asChange(t.change), ...(file ? { file } : {}) }]
    })
    .slice(0, 20)
  if (states.length < 2 || transitions.length < 1) return undefined
  return { title: clean(value.title, 80) || 'States', states, transitions }
}

const FLOW_INSTRUCTIONS = `Then describe how the change behaves at run time. "flows" lists up to 4 paths, the most important first, each as a sequence of up to 14 calls between up to 7 participants (apps, services, modules, queues, external systems), in the order they happen. Give a participant's or a step's main changed file as "file" when it has one, using an exact path from the list. Mark each step "added" (new in this change), "changed" (existing behaviour this change alters) or "unchanged" (existing behaviour the change relies on); "kind" is call, return or async (an event, queue message or webhook). Give a second, third or fourth flow only when it is a genuinely separate path (another trigger or another outcome, such as a refund next to a payment), never to pad; most changes have one. Use an empty "flows" list when the change has no run-time path worth drawing (docs, refactors, configuration). If the change adds or alters statuses or lifecycle states (an enum, a status field, a state machine), also fill "stateCharts" with one chart per separate state machine (up to 4), each with up to 9 states and 18 transitions marked added, changed or unchanged; otherwise use an empty list.`

const FLOW_SHAPE = `, "flows": [{"title": "...", "participants": [{"id": "a", "label": "Patient app", "file": "path or omit"}], "steps": [{"from": "a", "to": "b", "label": "requests the charge", "kind": "call|return|async", "change": "added|changed|unchanged", "file": "path or omit"}]}], "stateCharts": [{"title": "...", "states": [{"id": "AUTHORIZED", "label": "Authorized", "change": "added|changed|unchanged"}], "transitions": [{"from": "AUTHORIZED", "to": "PAID", "label": "capture succeeds", "change": "added|changed|unchanged", "file": "path or omit"}]}]`

export type PromptOptions = {
  /** Characters of diff the prompt may carry. */
  budget?: number
  /** Characters of any one file's diff, where the caller has already sized the parts. */
  perFileCap?: number
  /** Set when the change is mapped in parts: which part this is. */
  part?: { index: number; total: number }
}

export function buildPrompt(title: string, parsed: ParsedDiff, context = '', options: PromptOptions = {}): string {
  const budget = options.budget ?? 150_000
  const perFile = options.perFileCap ?? Math.max(2_000, Math.floor(budget / Math.max(1, parsed.files.length)))
  const list = parsed.files
    .map(f => `- ${f.path}${f.oldPath ? ` (renamed from ${f.oldPath})` : ''} [${f.status}] +${f.added} -${f.removed}`)
    .join('\n')
  let body = ''
  for (const file of parsed.files) {
    const patch = parsed.patches.get(file.path) ?? ''
    const isNoise = /(^|\/)(pnpm-lock\.yaml|package-lock\.json|yarn\.lock)$|\.min\.(js|css)$|\.map$/.test(file.path)
    const piece = isNoise
      ? `diff --git a/${file.path} b/${file.path}\n(lockfile/generated, omitted)\n`
      : patch.length > perFile
        ? `${patch.slice(0, perFile)}\n... (${patch.length - perFile} more characters of this file's diff omitted)\n`
        : patch
    if (body.length + piece.length > budget) {
      body += `\n... (remaining files' diffs omitted for size)\n`
      break
    }
    body += piece
  }

  const askFlow = options.part === undefined
  const partNote = options.part
    ? `\nThis change is large, so it is mapped in ${options.part.total} parts, and this is part ${options.part.index} of ${options.part.total}. Group ONLY the files listed below, give every one of them a group, and relate them only to each other.\n`
    : ''

  return `${context}You are helping a developer review a code change: ${title}
${partNote}
Group the changed files into a small number of themes (the logical changes a reviewer would think in, e.g. "new search endpoint", "schema field", "tests", "docs"), not by directory. Every file must appear in exactly one group. For each file give 1-3 terse notes on WHAT changed in it (behaviour, not line counts). Rate each group's review risk. Then give the order a reviewer should read the files in (the core change first, then its callers, then tests/docs), and any concerns worth a closer look (possible bugs, missing tests, breaking changes). Also list the meaningful relationships between changed files (a calls or imports b, a schema field is read by b, a migration backs a model change, a test covers b, a view renders b): up to 12, each with a label under 50 characters; skip trivial or purely directory-level links. Be concise: notes under 90 characters.${askFlow ? ` ${FLOW_INSTRUCTIONS}` : ''}

Reply with JSON only, no prose, no code fence, in exactly this shape:
{"summary": "one sentence", "groups": [{"title": "...", "kind": "feature|fix|refactor|test|docs|config|chore", "risk": "low|medium|high", "why": "one short line on what this group does", "files": [{"path": "exact path from the list", "notes": ["..."]}]}], "reviewOrder": ["path", ...], "concerns": ["..."], "links": [{"from": "path", "to": "path", "label": "calls the new endpoint"}]${askFlow ? FLOW_SHAPE : ''}}

Changed files:
${list}

Diff:
${body}`
}

const RISKS = ['low', 'medium', 'high'] as const

/** Reads the model's reply as themes; undefined when it is not the expected JSON. */
export function parseThemes(text: string, files: DiffMapFile[]): DiffMapThemes | undefined {
  const raw = readJson(text)
  if (typeof raw !== 'object' || raw === null || !Array.isArray((raw as { groups?: unknown }).groups)) return undefined
  const value = raw as Record<string, unknown>
  const strings = (v: unknown) => (Array.isArray(v) ? v.filter((s): s is string => typeof s === 'string') : [])

  const groups: DiffMapGroup[] = (value.groups as unknown[]).flatMap(g => {
    if (typeof g !== 'object' || g === null) return []
    const group = g as Record<string, unknown>
    const risk = RISKS.find(r => r === group.risk) ?? 'low'
    const groupFiles = Array.isArray(group.files)
      ? group.files.flatMap(f => {
          if (typeof f !== 'object' || f === null) return []
          const file = f as Record<string, unknown>
          return typeof file.path === 'string' ? [{ path: file.path, notes: strings(file.notes) }] : []
        })
      : []
    return [{
      title: typeof group.title === 'string' ? group.title : 'Changes',
      kind: typeof group.kind === 'string' ? group.kind : 'change',
      risk,
      why: typeof group.why === 'string' ? group.why : '',
      files: groupFiles,
    }]
  })

  const covered = new Set(groups.flatMap(g => g.files.map(f => f.path)))
  const missing = files.filter(f => !covered.has(f.path))
  if (missing.length > 0) {
    groups.push({
      title: 'Not grouped',
      kind: 'other',
      risk: 'low',
      why: 'Files the model left out',
      files: missing.map(f => ({ path: f.path, notes: [] })),
    })
  }

  const known = new Set(files.map(f => f.path))
  const links: DiffMapLink[] = (Array.isArray(value.links) ? value.links : []).flatMap((l: unknown) => {
    if (typeof l !== 'object' || l === null) return []
    const link = l as Record<string, unknown>
    const { from, to } = link
    if (typeof from !== 'string' || typeof to !== 'string' || from === to || !known.has(from) || !known.has(to)) return []
    return [{ from, to, label: typeof link.label === 'string' ? link.label : '' }]
  })

  // an older reply, or a model that kept to the old shape, gives one flow and one chart
  const flows = parseFlows(value.flows ?? value.flow, known)
  const stateCharts = parseStateCharts(value.stateCharts ?? value.states, known)

  return {
    summary: typeof value.summary === 'string' ? value.summary : '',
    groups,
    reviewOrder: strings(value.reviewOrder),
    concerns: strings(value.concerns),
    links: links.slice(0, 20),
    ...(flows.length > 0 ? { flows } : {}),
    ...(stateCharts.length > 0 ? { stateCharts } : {}),
  }
}

/** The second step of a large change: one summary and the links between the parts, from the parts' themes alone. */
export function buildStitchPrompt(title: string, parts: readonly DiffMapThemes[], budget = 60_000): string {
  let themes = ''
  for (const part of parts) {
    for (const group of part.groups) {
      const block = `- ${group.title} (${group.kind}, ${group.risk} risk): ${group.why}\n${group.files.map(f => `    ${f.path}${f.notes[0] ? ` - ${f.notes[0]}` : ''}`).join('\n')}\n`
      if (themes.length + block.length > budget) return finishStitch(title, `${themes}- ... (more themes omitted for size)\n`)
      themes += block
    }
  }
  return finishStitch(title, themes)
}

const finishStitch = (title: string, themes: string) => `You are helping a developer review a large code change: ${title}

It was mapped in separate parts. Below are the themes found, each with its files and a note on what changed. Write one sentence that summarises the whole change, and list the meaningful relationships BETWEEN files that belong to different themes (a calls or imports b, a schema field is read by b, a migration backs a model change, a test covers b, a view renders b): up to 15, each with a label under 50 characters, using the exact paths below. Skip trivial links. ${FLOW_INSTRUCTIONS.replace('Then describe', 'Finally describe').replace('from the list', 'from the themes')} You only have the themes, not the diffs, so keep the flow high-level.

Reply with JSON only, no prose, no code fence, in exactly this shape:
{"summary": "one sentence", "links": [{"from": "path", "to": "path", "label": "calls the new endpoint"}]${FLOW_SHAPE}}

Themes:
${themes}`

export type Stitch = { summary: string; links: DiffMapLink[]; flows?: DiffMapFlow[]; stateCharts?: DiffMapStateChart[] }

/** Reads the second step's reply; undefined when it is not the expected JSON. */
export function parseStitch(text: string, files: readonly DiffMapFile[]): Stitch | undefined {
  const raw = readJson(text)
  if (typeof raw !== 'object' || raw === null) return undefined
  const value = raw as Record<string, unknown>
  const known = new Set(files.map(f => f.path))
  const links: DiffMapLink[] = (Array.isArray(value.links) ? value.links : []).flatMap((l: unknown) => {
    if (typeof l !== 'object' || l === null) return []
    const link = l as Record<string, unknown>
    const { from, to } = link
    if (typeof from !== 'string' || typeof to !== 'string' || from === to || !known.has(from) || !known.has(to)) return []
    return [{ from, to, label: typeof link.label === 'string' ? link.label : '' }]
  })
  const flows = parseFlows(value.flows ?? value.flow, known)
  const stateCharts = parseStateCharts(value.stateCharts ?? value.states, known)
  return {
    summary: typeof value.summary === 'string' ? value.summary : '',
    links: links.slice(0, 15),
    ...(flows.length > 0 ? { flows } : {}),
    ...(stateCharts.length > 0 ? { stateCharts } : {}),
  }
}

