import type { DiffMapData, DiffMapLink } from '../types'
import { isDocs, isGenerated, isTest, reviewPaths } from './model'

export type StrategyKey = 'bottom-up' | 'top-down' | 'theme' | 'model'

export const STRATEGIES: { key: StrategyKey; label: string; blurb: string }[] = [
  { key: 'theme', label: 'By theme', blurb: "The model's themes, one after another." },
  { key: 'bottom-up', label: 'Bottom-up', blurb: 'Definitions before the code that uses them, then tests, then docs.' },
  { key: 'top-down', label: 'Top-down', blurb: 'Entry points first, then what they call, then tests, then docs.' },
  { key: 'model', label: "Model's order", blurb: "The model's own suggested order, untouched." },
]

export type DiagramStep = { path: string; reason: string; stage: string }
export type DiagramStage = { label: string; from: number; to: number }
export type DiagramOrder = { key: StrategyKey; label: string; blurb: string; steps: DiagramStep[]; stages: DiagramStage[] }

type Category = 'code' | 'tests' | 'docs' | 'generated'
const categoryOf = (path: string): Category => (isGenerated(path) ? 'generated' : isTest(path) ? 'tests' : isDocs(path) ? 'docs' : 'code')
const CATEGORY_LABEL: Record<Category, string> = { code: 'Code', tests: 'Tests', docs: 'Docs', generated: 'Generated, skim' }
const CATEGORY_RANK: Record<Category, number> = { code: 0, tests: 1, docs: 2, generated: 3 }

type CodeStage = 'foundations' | 'core' | 'entry' | 'independent'
const CODE_STAGE_LABEL: Record<CodeStage, string> = {
  foundations: 'Foundations',
  core: 'Core logic',
  entry: 'Callers and entry points',
  independent: 'Independent changes',
}
const BOTTOM_UP_STAGES: CodeStage[] = ['foundations', 'core', 'entry', 'independent']
const TOP_DOWN_STAGES: CodeStage[] = ['entry', 'core', 'foundations', 'independent']

const baseName = (path: string) => path.split('/').pop() ?? path

/**
 * Kahn's algorithm over `edges` (a pair means: first before second), ties and cycles broken by `tie`.
 * Always returns every path exactly once.
 */
function topological(paths: readonly string[], edges: readonly [string, string][], tie: (p: string) => number): string[] {
  const set = new Set(paths)
  const out = new Map<string, string[]>()
  const indeg = new Map<string, number>(paths.map(p => [p, 0]))
  for (const [a, b] of edges) {
    if (!set.has(a) || !set.has(b) || a === b) continue
    out.set(a, [...(out.get(a) ?? []), b])
    indeg.set(b, (indeg.get(b) ?? 0) + 1)
  }
  const left = new Set(paths)
  const result: string[] = []
  while (left.size > 0) {
    const pool = [...left].sort((x, y) => tie(x) - tie(y))
    const ready = pool.filter(p => (indeg.get(p) ?? 0) === 0)
    const next = ready[0] ?? pool.reduce((best, p) => ((indeg.get(p) ?? 0) < (indeg.get(best) ?? 0) ? p : best), pool[0] as string)
    left.delete(next)
    result.push(next)
    for (const b of out.get(next) ?? []) indeg.set(b, (indeg.get(b) ?? 0) - 1)
  }
  return result
}

function runsOf(steps: readonly DiagramStep[]): DiagramStage[] {
  const stages: DiagramStage[] = []
  steps.forEach((step, i) => {
    const last = stages[stages.length - 1]
    if (last && last.label === step.stage) last.to = i
    else stages.push({ label: step.stage, from: i, to: i })
  })
  return stages
}

const more = (n: number) => (n > 1 ? ` and ${n - 1} more` : '')

/** Every reading order the diagram offers, each with a reason per step and the stages it falls into. */
export function buildOrders(map: DiffMapData, links: readonly DiffMapLink[]): DiagramOrder[] {
  const model = reviewPaths(map)
  const modelIndex = new Map(model.map((p, i): [string, number] => [p, i]))
  const tie = (p: string) => modelIndex.get(p) ?? Number.MAX_SAFE_INTEGER
  const groupTitle = (p: string) => map.themes?.groups.find(g => g.files.some(f => f.path === p))?.title
  const groupWhy = (p: string) => map.themes?.groups.find(g => g.files.some(f => f.path === p))?.why ?? ''

  const dependents = (p: string) => links.filter(l => l.to === p) // they depend on p
  const dependencies = (p: string) => links.filter(l => l.from === p) // p depends on them
  const byCategory = (c: Category) => model.filter(p => categoryOf(p) === c)

  /** Code, tests, docs, generated: one dependency-ordered sequence, `bottomUp` choosing which way the links read. */
  const layered = (bottomUp: boolean): DiagramStep[] => {
    const code = byCategory('code')
    const codeSet = new Set(code)
    const inCode = (l: DiffMapLink) => codeSet.has(l.from) && codeSet.has(l.to)
    const codeLinks = links.filter(inCode)
    const stageOf = (p: string): CodeStage => {
      const deps = codeLinks.filter(l => l.from === p).length
      const users = codeLinks.filter(l => l.to === p).length
      if (deps === 0 && users === 0) return 'independent'
      if (deps === 0) return 'foundations'
      if (users === 0) return 'entry'
      return 'core'
    }
    // a file that is called must be read first going bottom-up, last going top-down
    const edges: [string, string][] = codeLinks.map(l => (bottomUp ? [l.to, l.from] : [l.from, l.to]))
    const position = new Map(topological(code, edges, tie).map((p, i): [string, number] => [p, i]))
    const stageOrder = bottomUp ? BOTTOM_UP_STAGES : TOP_DOWN_STAGES
    const codeOrdered = [...code].sort(
      (a, b) => stageOrder.indexOf(stageOf(a)) - stageOrder.indexOf(stageOf(b)) || (position.get(a) ?? 0) - (position.get(b) ?? 0),
    )

    const codeStep = (p: string): DiagramStep => {
      const stage = stageOf(p)
      const used = dependents(p)
      const uses = dependencies(p)
      let reason: string
      if (stage === 'independent') {
        const title = groupTitle(p)
        reason = title ? `independent change in ${title}` : 'independent change'
      } else if (bottomUp) {
        reason =
          used.length > 0
            ? `read before ${baseName((used[0] as DiffMapLink).from)} (${(used[0] as DiffMapLink).label || 'it depends on this'})${more(used.length)}`
            : `builds on ${baseName((uses[0] as DiffMapLink).to)} (${(uses[0] as DiffMapLink).label || 'it depends on it'})${more(uses.length)}`
      } else {
        reason =
          uses.length > 0 && used.length === 0
            ? `entry point: ${(uses[0] as DiffMapLink).label || 'calls'} ${baseName((uses[0] as DiffMapLink).to)}${more(uses.length)}`
            : used.length > 0
              ? `called by ${baseName((used[0] as DiffMapLink).from)} (${(used[0] as DiffMapLink).label || 'it uses this'})${more(used.length)}`
              : `builds on ${baseName((uses[0] as DiffMapLink).to)}`
      }
      return { path: p, reason, stage: CODE_STAGE_LABEL[stage] }
    }

    // tests follow the code they cover, in the order that code is read
    const at = new Map(codeOrdered.map((p, i): [string, number] => [p, i]))
    const testOrder = (p: string) =>
      Math.min(...links.filter(l => l.from === p || l.to === p).map(l => at.get(l.from === p ? l.to : l.from) ?? Infinity), Infinity)
    const tests = [...byCategory('tests')].sort((a, b) => testOrder(a) - testOrder(b) || tie(a) - tie(b))
    const testStep = (p: string): DiagramStep => {
      const link = links.find(l => (l.from === p || l.to === p) && codeSet.has(l.from === p ? l.to : l.from))
      const target = link ? baseName(link.from === p ? link.to : link.from) : ''
      return { path: p, reason: target ? `covers ${target}: read after the code` : 'test: read after the code', stage: CATEGORY_LABEL.tests }
    }

    return [
      ...codeOrdered.map(codeStep),
      ...tests.map(testStep),
      ...byCategory('docs').map((p): DiagramStep => ({ path: p, reason: 'documentation: read last', stage: CATEGORY_LABEL.docs })),
      ...byCategory('generated').map((p): DiagramStep => ({ path: p, reason: 'generated: skim only', stage: CATEGORY_LABEL.generated })),
    ]
  }

  const byTheme = (): DiagramStep[] => {
    const seen = new Set<string>()
    const steps: DiagramStep[] = []
    for (const group of map.themes?.groups ?? []) {
      const inGroup = group.files.filter(f => modelIndex.has(f.path) && !seen.has(f.path)).sort((a, b) => tie(a.path) - tie(b.path))
      for (const { path: p, notes } of inGroup) {
        seen.add(p)
        // the stage heading already names the theme, so a row says what is particular to its file
        steps.push({ path: p, reason: notes[0] ?? (group.why ? `${group.title}: ${group.why}` : group.title), stage: group.title })
      }
    }
    for (const p of model) if (!seen.has(p)) steps.push({ path: p, reason: 'not part of a theme', stage: 'Other files' })
    return steps
  }

  const modelOrder = (): DiagramStep[] =>
    model.map(p => ({ path: p, reason: groupWhy(p) ? `the model's suggestion (${groupWhy(p)})` : "the model's suggestion", stage: CATEGORY_LABEL[categoryOf(p)] }))

  const build: Record<StrategyKey, () => DiagramStep[]> = {
    'bottom-up': () => layered(true),
    'top-down': () => layered(false),
    theme: byTheme,
    model: modelOrder,
  }
  return STRATEGIES.map(s => {
    const steps = build[s.key]()
    return { key: s.key, label: s.label, blurb: s.blurb, steps, stages: runsOf(steps) }
  })
}

