import { isDocs, isGenerated, isTest } from './model'

export type SensitiveTag = { id: string; label: string; why: string }

type Rule = SensitiveTag & { path?: RegExp; added?: RegExp }

/** Areas where a mistake costs more than usual: found from the path, or from what the change adds. */
const RULES: Rule[] = [
  {
    id: 'rbac',
    label: 'RBAC',
    why: 'access control: check who can reach this and what each role may do',
    path: /(^|\/)rbac(\/|-)|access-manager|db-access|permission/i,
  },
  {
    id: 'auth',
    label: 'Auth',
    why: 'authentication and sessions: check token, session and login handling',
    path: /(^|\/)(auth|authentication|cognito)(\/|[-.])|login|(^|[/-])session/i,
  },
  {
    id: 'crypto',
    label: 'Crypto',
    why: 'encryption and keys: check key handling, and that nothing sensitive is logged or sent in the clear',
    path: /encrypt|decrypt|crypto|ecies|private-?key/i,
  },
  {
    id: 'payments',
    label: 'Payments',
    why: 'money: check amounts, currency, idempotency and the refund paths',
    path: /payment|stripe|unzer|invoice|prepay|refund|voucher|billing|subscription/i,
  },
  {
    id: 'nhis',
    label: 'NHIS',
    why: 'medical records sent to the national system: check the mappings and required fields',
    path: /nhis|e-?prescription|e-?referral|medical-notice/i,
  },
  {
    id: 'migration',
    label: 'Migration',
    why: 'database migration: check it is reversible and safe on existing data',
    path: /(^|\/)migrations\//,
  },
  {
    id: 'config',
    label: 'Config',
    why: 'environment or deploy configuration: check for secrets and per-environment values',
    path: /(^|\/)(\.env[^/]*|docker-compose[^/]*|deploy\/|Dockerfile|Jenkinsfile)/,
  },
  {
    id: 'dynamic-code',
    label: 'Dynamic code',
    why: 'code run from a string or a shell: check that the input cannot be controlled by an attacker',
    added: /\beval\(|new Function\(|child_process|\b(exec|execSync|spawnSync)\(/,
  },
  {
    id: 'html',
    label: 'Raw HTML',
    why: 'raw HTML insertion: check that the content is escaped or sanitised',
    added: /dangerouslySetInnerHTML|\.innerHTML\s*=/,
  },
  {
    id: 'secret',
    label: 'Secret?',
    why: 'looks like a credential in added code: check it is not a real one',
    added: /(api[_-]?key|secret|password|token)\s*[:=]\s*["'][A-Za-z0-9_-]{16,}["']/i,
  },
]

/** The sensitive areas one changed file touches. Tests, docs and generated files never count. */
export function sensitiveTags(path: string, patch: string): SensitiveTag[] {
  if (isTest(path) || isDocs(path) || isGenerated(path)) return []
  const added = patch
    .split('\n')
    .filter(l => l.startsWith('+') && !l.startsWith('+++'))
    .join('\n')
  return RULES.filter(r => (r.path?.test(path) ?? false) || (r.added?.test(added) ?? false)).map(({ id, label, why }) => ({ id, label, why }))
}

