import type { EngineInterface } from 'claude-code'

import type { DiffMapThemes } from '../types'

const MAX_ENTRIES = 40

export async function sha256(text: string): Promise<string> {
  const bytes = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(text))
  return [...new Uint8Array(bytes)].map(b => b.toString(16).padStart(2, '0')).join('')
}

/** Writes `value` under `key` and keeps the newest MAX_ENTRIES keys of that kind, dropping the oldest. */
async function remember($: EngineInterface, kind: string, key: string, value: unknown) {
  const indexKey = `diffmap:index:${kind}`
  const raw = await $.store.get(indexKey)
  const index = Array.isArray(raw) ? raw.filter((k): k is string => typeof k === 'string') : []
  const next = [...index.filter(k => k !== key), key]
  const dropped = next.splice(0, Math.max(0, next.length - MAX_ENTRIES))
  for (const old of dropped) await $.store.delete(`diffmap:${kind}:${old}`)
  await $.store.set(`diffmap:${kind}:${key}`, value)
  await $.store.set(indexKey, next)
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

export async function loadCachedThemes($: EngineInterface, key: string): Promise<DiffMapThemes | undefined> {
  const raw = await $.store.get(`diffmap:themes:${key}`)
  if (!isObject(raw) || !Array.isArray(raw.groups)) return undefined
  return raw as unknown as DiffMapThemes
}

export async function saveCachedThemes($: EngineInterface, key: string, themes: DiffMapThemes) {
  await remember($, 'themes', key, themes)
}

files.hooks/diagram-data.ts:
import type { DiffMapData, DiffMapFile, DiffMapFlow, DiffMapLink, DiffMapSensitive, DiffMapStateChart } from '../types'
import { groupOf, isDocs, isGenerated, isTest, linksFor } from './model'
import { buildOrders } from './review-order'
import type { DiagramOrder, StrategyKey } from './review-order'

export const MAX_PATCH = 200_000

export type Lane = { title: string; kind: string; risk: 'low' | 'medium' | 'high'; why: string; files: string[] }

/** Lanes are the model's themes; with none readable the top-level folders stand in. */
export function lanesOf(map: DiffMapData): Lane[] {
  const known = new Set(map.files.map(f => f.path))
  const lanes: Lane[] = (map.themes?.groups ?? [])
    .map(g => ({ title: g.title, kind: g.kind, risk: g.risk, why: g.why, files: g.files.map(f => f.path).filter(p => known.has(p)) }))
    .filter(l => l.files.length > 0)
  if (lanes.length > 0) return lanes

  const folders = new Map<string, string[]>()
  for (const file of map.files) {
    const top = file.path.includes('/') ? (file.path.split('/')[0] ?? '.') : '.'
    folders.set(top, [...(folders.get(top) ?? []), file.path])
  }
  return [...folders.entries()].map(([title, files]) => ({ title: title === '.' ? 'Top level' : `${title}/`, kind: 'folder', risk: 'low' as const, why: '', files }))
}

const laneIndex = (lanes: readonly Lane[]) => new Map(lanes.flatMap((l, i) => l.files.map((p): [string, number] => [p, i])))

/**
 * Callers to the left, what they call to the right: a link runs from the file that depends
 * on the other, so lanes are taken in dependency order (Kahn), the original order breaking ties
 * and cycles.
 */
export function orderLanes(lanes: readonly Lane[], links: readonly DiffMapLink[]): Lane[] {
  const at = laneIndex(lanes)
  const edges = new Set<string>()
  for (const link of links) {
    const a = at.get(link.from)
    const b = at.get(link.to)
    if (a !== undefined && b !== undefined && a !== b) edges.add(`${a}>${b}`)
  }
  const remaining = new Set(lanes.map((_, i) => i))
  const incoming = (i: number) => [...edges].filter(e => {
    const [from, to] = e.split('>').map(Number)
    return to === i && from !== undefined && remaining.has(from)
  }).length

  const out: Lane[] = []
  while (remaining.size > 0) {
    const candidates = [...remaining].sort((a, b) => a - b)
    const next = candidates.find(i => incoming(i) === 0) ?? candidates.reduce((best, i) => (incoming(i) < incoming(best) ? i : best))
    remaining.delete(next)
    const lane = lanes[next]
    if (lane) out.push(lane)
  }
  return out
}

/** Reorders files inside each lane by the average height of what they link to, to cut crossings. */
export function orderFiles(lanes: readonly Lane[], links: readonly DiffMapLink[]): Lane[] {
  const result = lanes.map(l => ({ ...l, files: [...l.files] }))
  const at = laneIndex(result)
  const pos = new Map<string, number>()
  const place = (lane: Lane) => lane.files.forEach((p, i) => pos.set(p, (i + 0.5) / lane.files.length))
  result.forEach(place)

  const neighbours = new Map<string, string[]>()
  for (const { from, to } of links) {
    if (at.get(from) === undefined || at.get(to) === undefined || at.get(from) === at.get(to)) continue
    neighbours.set(from, [...(neighbours.get(from) ?? []), to])
    neighbours.set(to, [...(neighbours.get(to) ?? []), from])
  }

  const sweep = (order: number[]) => {
    for (const li of order) {
      const lane = result[li]
      if (!lane) continue
      const score = (p: string) => {
        const near = neighbours.get(p)
        if (!near || near.length === 0) return pos.get(p) ?? 0
        return near.reduce((sum, n) => sum + (pos.get(n) ?? 0), 0) / near.length
      }
      const scored = lane.files.map((p, i) => ({ p, i, s: score(p) }))
      scored.sort((a, b) => a.s - b.s || a.i - b.i)
      lane.files = scored.map(x => x.p)
      place(lane)
    }
  }
  const forward = result.map((_, i) => i)
  sweep(forward)
  sweep([...forward].reverse())
  return result
}

export type DiagramFile = {
  status: DiffMapFile['status']
  oldPath: string | null
  added: number
  removed: number
  group: string | null
  risk: 'low' | 'medium' | 'high' | null
  why: string
  notes: string[]
  checks: { severity: 'warn' | 'info'; text: string }[]
  /** Sensitive areas this file touches. */
  risks: DiffMapSensitive[]
  links: ReturnType<typeof linksFor>
  isTest: boolean
  isDocs: boolean
  isGenerated: boolean
  linked: boolean
  patch: string
  full: string | null
}

export type DiagramRiskTag = DiffMapSensitive & { count: number }

export type DiagramData = {
  title: string
  /** Where the page keeps what was ticked off in the browser. */
  storeKey: string
  strategy: StrategyKey
  orders: DiagramOrder[]
  lanes: Lane[]
  files: Record<string, DiagramFile>
  links: DiffMapLink[]
  /** Every sensitive area the change touches, with how many files each covers. */
  riskTags: DiagramRiskTag[]
  /** The run-time sequences the model drew, the main one first; none when the change has no run-time path. */
  flows: DiffMapFlow[]
  /** The lifecycle states the change adds or alters, a chart per state machine. */
  stateCharts: DiffMapStateChart[]
  concerns: string[]
  general: { severity: 'warn' | 'info'; text: string }[]
}

export type DiagramOptions = {
  /** The review order the page opens on; the computed one when there are no themes to read by. */
  defaultStrategy?: StrategyKey
}

export function buildDiagramData(map: DiffMapData, fullFiles: Readonly<Record<string, string>> = {}, options: DiagramOptions = {}): DiagramData {
  const links = (map.themes?.links ?? []).filter(l => map.files.some(f => f.path === l.from) && map.files.some(f => f.path === l.to))
  const linked = new Set(links.flatMap(l => [l.from, l.to]))
  const lanes = orderFiles(orderLanes(lanesOf(map), links), links)
  const hasThemes = (map.themes?.groups.length ?? 0) > 0
  const wanted = options.defaultStrategy ?? 'theme'

  const files = Object.fromEntries(
    map.files.map((file): [string, DiagramFile] => {
      const found = groupOf(map, file.path)
      const patch = map.patches?.[file.path] ?? ''
      return [
        file.path,
        {
          status: file.status,
          oldPath: file.oldPath ?? null,
          added: file.added,
          removed: file.removed,
          group: found?.group.title ?? null,
          risk: found?.group.risk ?? null,
          why: found?.group.why ?? '',
          notes: found?.notes ?? [],
          checks: (map.checks ?? []).filter(c => c.path === file.path).map(c => ({ severity: c.severity, text: c.text })),
          risks: map.sensitive?.[file.path] ?? [],
          links: linksFor(links, file.path),
          isTest: isTest(file.path),
          isDocs: isDocs(file.path),
          isGenerated: isGenerated(file.path),
          linked: linked.has(file.path),
          patch: patch.length > MAX_PATCH ? `${patch.slice(0, MAX_PATCH)}\n… (diff cut at ${MAX_PATCH} characters)` : patch,
          full: fullFiles[file.path] ?? null,
        },
      ]
    }),
  )

  const tags = new Map<string, DiagramRiskTag>()
  for (const file of Object.values(files)) {
    for (const risk of file.risks) tags.set(risk.id, { ...risk, count: (tags.get(risk.id)?.count ?? 0) + 1 })
  }

  return {
    title: map.title,
    storeKey: map.storeKey,
    // the model's themes are the natural reading order; without any there is nothing to read by
    strategy: wanted === 'theme' && !hasThemes ? 'bottom-up' : wanted,
    orders: buildOrders(map, links),
    lanes,
    files,
    links,
    riskTags: [...tags.values()].sort((a, b) => b.count - a.count || a.label.localeCompare(b.label)),
    // a map kept before there could be several holds a single flow and a single chart
    flows: map.themes?.flows ?? (map.themes?.flow ? [map.themes.flow] : []),
    stateCharts: map.themes?.stateCharts ?? (map.themes?.states ? [map.themes.states] : []),
    concerns: map.themes?.concerns ?? [],
    general: (map.checks ?? []).filter(c => c.path === undefined).map(c => ({ severity: c.severity, text: c.text })),
  }
}

