files.types/index.d.ts:
export type DiffMapStatus = 'added' | 'deleted' | 'renamed' | 'modified' | 'binary'

export type DiffMapFile = {
  path: string
  oldPath?: string
  status: DiffMapStatus
  added: number
  removed: number
  /** Function/section names from the hunk headers, deduplicated. */
  contexts: string[]
}

export type DiffMapGroup = {
  title: string
  kind: string
  risk: 'low' | 'medium' | 'high'
  why: string
  files: { path: string; notes: string[] }[]
}

/** A relationship between two changed files, as the model read it from the diff. */
export type DiffMapLink = {
  from: string
  to: string
  label: string
}

/** What this change does to a step, state or transition. */
export type DiffMapChange = 'added' | 'changed' | 'unchanged'

/** One call in the run-time sequence the change takes part in. */
export type DiffMapFlowStep = {
  from: string
  to: string
  label: string
  kind: 'call' | 'return' | 'async'
  change: DiffMapChange
  /** The changed file that implements the step, when there is one. */
  file?: string
}

/** The main run-time path as a sequence of calls between the parts of the system. */
export type DiffMapFlow = {
  title: string
  participants: { id: string; label: string; file?: string }[]
  steps: DiffMapFlowStep[]
}

/** The statuses a change adds or alters, as a chart of states and the moves between them. */
export type DiffMapStateChart = {
  title: string
  states: { id: string; label: string; change: DiffMapChange }[]
  transitions: { from: string; to: string; label: string; change: DiffMapChange; file?: string }[]
}

export type DiffMapThemes = {
  summary: string
  groups: DiffMapGroup[]
  reviewOrder: string[]
  concerns: string[]
  links: DiffMapLink[]
  /** How the change behaves at run time, the main path first; absent when it has none worth drawing. */
  flows?: DiffMapFlow[]
  /** The lifecycle states the change adds or alters, one chart per state machine; absent when it touches none. */
  stateCharts?: DiffMapStateChart[]
  /** Maps kept before there could be several: a single flow and a single chart of states. */
  flow?: DiffMapFlow
  states?: DiffMapStateChart
}

/** A finding of the repo-convention checks (computed locally, no model). */
export type DiffMapCheck = {
  severity: 'warn' | 'info'
  text: string
  path?: string
}

/** A sensitive area a changed file touches (access control, payments, migrations, ...). */
export type DiffMapSensitive = {
  id: string
  label: string
  why: string
}

export type DiffMapData = {
  /** What was mapped: `local`, `pr:<number>` or `pr:<owner/name>#<number>`; a repeat of the same request reopens it. */
  key: string
  /** The repository a pull request was read from, when it was named rather than taken from the folder. */
  repo?: string
  /** Where per-map values are kept: the repo folder plus `key`. */
  storeKey: string
  source: string
  title: string
  files: DiffMapFile[]
  phase: 'loading' | 'thinking' | 'done' | 'error'
  error?: string
  themes?: DiffMapThemes
  /** The model's raw reply, when it could not be read as JSON. */
  rawThemes?: string
  /** Each changed file's unified diff, by path. */
  patches?: Record<string, string>
  checks?: DiffMapCheck[]
  /** The sensitive areas each file touches, by path; only files that touch any are listed. */
  sensitive?: Record<string, DiffMapSensitive[]>
  /** True when the themes came from the cross-session cache, not the model. */
  isCached?: boolean
}

declare module 'claude-code' {
  interface PluginState {
    'review-map': {
      /** The last mapped change, kept so the same request can reopen the diagram. */
      data: DiffMapData | null
    }
  }
}
